"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9792],{42257:e=>{e.exports=JSON.parse('{"functions":[{"name":"timeout","desc":"Calls `callback` once at least `delay` seconds have passed, checking every\\n`RunService.Stepped`. Does not yield.\\n\\n#### Example:\\n```lua\\nSystemUtil.timeout(1, function()\\n\\tprint(\\"One second later\\")\\nend)\\n```","params":[{"name":"delay","desc":"Seconds to wait.","lua_type":"number"},{"name":"callback","desc":"Receives the seconds elapsed since the timeout started.","lua_type":"(number) -> ()"}],"returns":[],"function_type":"static","source":{"line":32,"path":"src/SystemUtil.luau"}},{"name":"interval","desc":"Calls `callback` every `interval` seconds, checking every `RunService.Stepped`.\\nEach call runs in its own thread. Return `false` from the callback, or call\\n`:Disconnect()` on the returned connection, to stop the interval.\\n\\n#### Example:\\n```lua\\nlocal ticks = 0\\nSystemUtil.interval(1, function()\\n\\tticks += 1\\n\\treturn ticks < 10 -- stop after 10 ticks\\nend)\\n```","params":[{"name":"interval","desc":"Seconds between calls.","lua_type":"number"},{"name":"callback","desc":"Receives the seconds elapsed since the interval started and the last frame\'s delta time.","lua_type":"(number, number) -> boolean?"}],"returns":[{"desc":"","lua_type":"RBXScriptConnection"}],"function_type":"static","source":{"line":71,"path":"src/SystemUtil.luau"}},{"name":"inTable","desc":"Checks if a value is in a table.\\n\\n#### Example:\\n```lua\\nSystemUtil.inTable({ 1, 2, 3 }, 2) -- true\\nSystemUtil.inTable({ 1, 2, 3 }, 4) -- false\\nSystemUtil.inTable({ Part, 2, 3, Part2 = true }, Part) -- true\\n```","params":[{"name":"searchTable","desc":"","lua_type":"{ [any]: any }"},{"name":"target","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":114,"path":"src/SystemUtil.luau"}},{"name":"disconnect","desc":"Disconnects a connection, or every connection in an array. Nil values and\\nnon-connections in the array are skipped.\\n\\n```lua\\nSystemUtil.disconnect(connection)\\nSystemUtil.disconnect({ connectionA, connectionB })\\n```","params":[{"name":"connection","desc":"","lua_type":"RBXScriptConnection? | { RBXScriptConnection? }"}],"returns":[],"function_type":"static","source":{"line":138,"path":"src/SystemUtil.luau"}},{"name":"getProductInfo","desc":"Returns `MarketplaceService:GetProductInfo` for a product. Successful results are\\ncached for the lifetime of the server or client, and failed requests return nil\\ninstead of erroring.\\n\\n```lua\\nlocal info = SystemUtil.getProductInfo(productId, Enum.InfoType.Product)\\nif info then\\n\\tprint(info.Name, info.PriceInRobux)\\nend\\n```","params":[{"name":"productId","desc":"","lua_type":"number"},{"name":"infoType","desc":"Defaults to `Enum.InfoType.Asset`.","lua_type":"Enum.InfoType?"}],"returns":[{"desc":"","lua_type":"{ [any]: any }?"}],"function_type":"static","yields":true,"source":{"line":177,"path":"src/SystemUtil.luau"}},{"name":"isMobile","desc":"Returns whether the player is on a touch device: touch is enabled and neither a\\nkeyboard nor a mouse is. In Studio only `TouchEnabled` is checked, so the device\\nemulator counts as mobile.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","realm":["Client"],"source":{"line":207,"path":"src/SystemUtil.luau"}},{"name":"isConsole","desc":"Returns whether a gamepad is enabled. This is also true on PC or mobile while a\\ncontroller is connected.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","realm":["Client"],"source":{"line":222,"path":"src/SystemUtil.luau"}}],"properties":[],"types":[],"name":"SystemUtil","desc":"General runtime helpers: frame-driven timers, disconnecting connections, cached\\nproduct info and platform checks.","source":{"line":8,"path":"src/SystemUtil.luau"}}')}}]);